return [
    ['name' => 'niveau_connaissance_simple', 'formula' => '(  (%assurance_vie_et_capitalisation_profil_investisseur% || 0)  + (%reponse_1_assurance_vie_et_capitalisation_profil_investisseur% || 0)  + (%reponse_2_assurance_vie_et_capitalisation_profil_investisseur% || 0)  + (%pea_et_comptes_titres_profil_investisseur% || 0)  + (%reponse_1_pea_et_comptes_titres_profil_investisseur% || 0)  + (%reponse_2_pea_et_comptes_titres_profil_investisseur% || 0)  + (%epargne_retraite_et_entreprise_profil_investisseur% || 0)  + (%reponse_1_epargne_retraite_et_entreprise_profil_investisseur% || 0)  + (%epargne_salariale_profil_investisseur% || 0)  + (%reponse_1_epargne_salariale_profil_investisseur% || 0)  + (%connaissance_fonds_euros_profil_investisseur% || 0)  + (%reponse_1_fonds_euros_profil_investisseur% || 0)  + (%connaissance_produits_monetaires_profil_investisseur% || 0)  + (%reponse_1_produits_monetaires_profil_investisseur% || 0)  + (%connaissance_produits_obligataires_profil_investisseur% || 0)  + (%reponse_1_produits_obligataires_profil_investisseur% || 0)  + (%connaissance_produits_actions_profil_investisseur% || 0)  + (%reponse_1_produits_actions_profil_investisseur% || 0)) / 80 * 10'],
    ['name' => 'niveau_experience_simple', 'formula' => '(  (%reponse_2_fonds_euros_profil_investisseur% || 0)  + (%reponse_2_produits_monetaires_profil_investisseur% || 0)  + (%reponse_2_produits_obligataires_profil_investisseur% || 0)  + (%reponse_2_produits_actions_profil_investisseur% || 0)) / 40 * 10'],
    ['name' => 'niveau_connaissance_intermediaire', 'formula' => '(  (%connaissance_scpi_profil_investisseur% || 0)  + (%reponse_1_scpi_profil_investisseur% || 0)  + (%connaissance_ocpi_profil_investisseur% || 0)  + (%reponse_1_ocpi_profil_investisseur% || 0)  + (%connaissance_capital_investissement_ou_private_equity_fcpr_fcpi_fip_profil_investisseur% || 0)  + (%reponse_1_capital_investissement_ou_private_equity_fcpr_fcpi_fip_profil_investisseur% || 0)  + (%connaissance_produits_structures_titres_de_creance_structures_profil_investisseur% || 0)  + (%reponse_1_produits_structures_titres_de_creance_structures_profil_investisseur% || 0)  + (%connaissance_sofica_profil_investisseur% || 0)  + (%reponse_1_sofica_profil_investisseur% || 0)  + (%connaissance_produits_obligataires_complexes_profil_investisseur% || 0)  + (%reponse_1_produits_obligataires_complexes_profil_investisseur% || 0)  + (%connaissance_produits_actions_complexes_profil_investisseur% || 0)  + (%reponse_1_produits_actions_complexes_profil_investisseur% || 0)) / 70 * 10'],
    ['name' => 'niveau_experience_intermediaire', 'formula' => '(  (%reponse_2_scpi_profil_investisseur% || 0)  + (%reponse_2_ocpi_profil_investisseur% || 0)  + (%reponse_2_capital_investissement_ou_private_equity_fcpr_fcpi_fip_profil_investisseur% || 0)  + (%reponse_2_produits_structures_titres_de_creance_structures_profil_investisseur% || 0)  + (%reponse_2_sofica_profil_investisseur% || 0)  + (%reponse_2_produits_obligataires_complexes_profil_investisseur% || 0)  + (%reponse_2_produits_actions_complexes_profil_investisseur% || 0)) / 70 * 10'],
    ['name' => 'niveau_connaissance_complexe', 'formula' => '(  (%connaissance_tracker_profil_investisseur% || 0)  + (%reponse_1_tracker_profil_investisseur% || 0)  + (%connaissance_cfd_profil_investisseur% || 0)  + (%reponse_1_cfd_profil_investisseur% || 0)  + (%connaissance_futures_profil_investisseur% || 0)  + (%reponse_1_futures_profil_investisseur% || 0)  + (%connaissance_options_profil_investisseur% || 0)  + (%reponse_1_options_profil_investisseur% || 0)  + (%connaissance_warrants_profil_investisseur% || 0)  + (%reponse_1_warrants_profil_investisseur% || 0)  + (%connaissance_turbos_profil_investisseur% || 0)  + (%reponse_1_turbos_profil_investisseur% || 0)) / 60 * 10'],
    ['name' => 'niveau_experience_complexe', 'formula' => '(  (%reponse_2_tracker_profil_investisseur% || 0)  + (%reponse_2_cfd_profil_investisseur% || 0)  + (%reponse_2_futures_profil_investisseur% || 0)  + (%reponse_2_options_profil_investisseur% || 0)  + (%reponse_2_warrants_profil_investisseur% || 0)  + (%reponse_2_turbos_profil_investisseur% || 0)) / 60 * 10'],
