    ['name' => 'score_complexe_echelle', 'formula' => '(%score_complexe_resultat% <= 2) ? "🔴 Non adapté" : (%score_complexe_resultat% <= 4) ? "🟠 Connaissance limitée" : (%score_complexe_resultat% <= 6) ? "🟠 Connaissance intermédiaire" : (%score_complexe_resultat% <= 8) ? "🟢 Bonne maîtrise" : "🟢 Expertise"'],
    ['name' => 'score_connaissance_global', 'formula' => '((%niveau_connaissance_simple% || 0) * 0.3)+ ((%niveau_connaissance_intermediaire% || 0) * 0.3)+ ((%niveau_connaissance_complexe% || 0) * 0.4)'],
    ['name' => 'score_connaissance_global_echelle', 'formula' => '(%score_connaissance_global% <= 2) ? "🔴 Très faible" : (%score_connaissance_global% <= 4) ? "🟠 Faible" : (%score_connaissance_global% <= 6) ? "🟢 Bonne" : (%score_connaissance_global% <= 8) ? "🟢 Avancée" : "🟢 Expertise"'],
    ['name' => 'score_experience_global', 'formula' => '((%niveau_experience_simple% || 0) * 0.2)+ ((%niveau_experience_intermediaire% || 0) * 0.35)+ ((%niveau_experience_complexe% || 0) * 0.45)'],
    ['name' => 'score_experience_global_echelle', 'formula' => '(%score_experience_global% <= 2) ? "🔴 Débutant" : (%score_experience_global% <= 4) ? "🟠 Basique" : (%score_experience_global% <= 6) ? "🟢 Intermédiaire" : (%score_experience_global% <= 8) ? "🟢 Avancé" : "🟢 Expert"'],
    ['name' => 'score_capacite_financiere', 'formula' => '(  (%risque_4_profil_investisseur% || 0)  + (%risque_5_profil_investisseur% || 0)  + (%risque_6_profil_investisseur% || 0)  + (%risque_7_profil_investisseur% || 0)  + (%risque_8_profil_investisseur% || 0)) / 50 * 10'],
    ['name' => 'score_capacite_financiere_echelle', 'formula' => '(%score_capacite_financiere% <= 2) ? "🔴 Très faible" : (%score_capacite_financiere% <= 4) ? "🟠 Faible" : (%score_capacite_financiere% <= 6) ? "🟢 Adéquate" : (%score_capacite_financiere% <= 8) ? "🟢 Confortable" : "🟢 Très confortable"'],
    ['name' => 'score_contrainte_financiere', 'formula' => '(  (%risque_9_profil_investisseur% || 0)  + (%risque_10_profil_investisseur% || 0)  + (%risque_11_profil_investisseur% || 0)  + (%risque_12_profil_investisseur% || 0)  + (%risque_13_profil_investisseur% || 0)) / 50 * 10'],
    ['name' => 'd1_tolerance_declarative', 'formula' => '(  (%aversion_1_profil_investisseur% || 0)  + (%aversion_2_profil_investisseur% || 0)  + (%aversion_4_profil_investisseur% || 0)  + (%aversion_5_profil_investisseur% || 0)  + (%aversion_6_profil_investisseur% || 0)  + (%aversion_7_profil_investisseur% || 0)) / 60 * 10'],
    ['name' => 'd3_comportement_risque', 'formula' => '(  (%aversion_3_profil_investisseur% || 0)  + (%aversion_8_profil_investisseur% || 0)  + (%aversion_9_profil_investisseur% || 0)  + (%aversion_10_profil_investisseur% || 0)  + (%aversion_11_profil_investisseur% || 0)) / 50 * 10'],
    ['name' => 'score_tolerance_risque', 'formula' => '((%d1_tolerance_declarative% || 0) * 0.5)+ ((%d3_comportement_risque% || 0) * 0.5)'],
    ['name' => 'score_tolerance_risque_echelle', 'formula' => '(%score_tolerance_risque% <= 2) ? "🔴 Très faible" : (%score_tolerance_risque% <= 4) ? "🔴 Faible" : (%score_tolerance_risque% <= 6) ? "🟠 Modérée" : (%score_tolerance_risque% <= 8) ? "🟢 Modérée à élevée" : "🟢 Élevée"'],
    ['name' => 'score_capacite_subir_pertes', 'formula' => '(  (    (%score_capacite_financiere% || 0)    - (%score_contrainte_financiere% || 0)    + (%score_tolerance_risque% || 0)    + (%preference_1_profil_investisseur% || 0)  ) < 0) ? 0:(  (%score_capacite_financiere% || 0)  - (%score_contrainte_financiere% || 0)  + (%score_tolerance_risque% || 0)  + (%preference_1_profil_investisseur% || 0)) / 30 * 10'],
    ['name' => 'score_capacite_subir_pertes_echelle', 'formula' => '(%score_capacite_subir_pertes% <= 2) ? "Très faible": (%score_capacite_subir_pertes% <= 4) ? "Faible": (%score_capacite_subir_pertes% <= 6) ? "Modérée": (%score_capacite_subir_pertes% <= 8) ? "Élevée": "Très élevée"'],
    ['name' => 'profil_risque_final', 'formula' => '(  (%score_connaissance_global% || 0)  + (%score_experience_global% || 0)  + (%score_capacite_subir_pertes% || 0)) / 30 * 10'],
    ['name' => 'profil_risque_final_echelle', 'formula' => '(%profil_risque_final% <= 2) ? "Conservateur": (%profil_risque_final% <= 4) ? "Prudent": (%profil_risque_final% <= 6) ? "Équilibré": (%profil_risque_final% <= 8) ? "Équilibré dynamique": "Dynamique"'],
    ['name' => 'alerte_client_fragile', 'formula' => '(  (%score_capacite_subir_pertes% <= 2)  || (%score_capacite_financiere% <= 2)  || ((%score_contrainte_financiere% >= 8) && (%score_capacite_financiere% <= 4))) ? 2: (  (%score_capacite_subir_pertes% <= 4)  || ((%score_contrainte_financiere% >= 6) && (%score_capacite_financiere% <= 4))) ? 1: 0'],
    ['name' => 'alerte_client_fragile_echelle', 'formula' => '(%alerte_client_fragile% == 2) ? "🔴 Client fragile" : (%alerte_client_fragile% == 1) ? "🟠 Vigilance" : "🟢 Profil cohérent"'],
    ['name' => 'alerte_objectif_levier', 'formula' => '((%score_tolerance_risque% - %score_capacite_financiere%) > 5) ? 2: ((%score_tolerance_risque% - %score_capacite_financiere%) > 3) ? 1: 0'],
    ['name' => 'alerte_objectif_levier_echelle', 'formula' => '(%alerte_objectif_levier% == 2) ? "🔴 Incohérence forte – tolérance incompatible avec la capacité financière": (%alerte_objectif_levier% == 1) ? "🟠 Vigilance – objectif ambitieux": "🟢 Cohérent" '],
