    ['name' => 'alerte_detention_sans_experience_marches_echelle', 'formula' => '(%alerte_detention_sans_experience_marche% == 2) ? "🔴 Détention incohérente – connaissance et expérience insuffisantes" : (%alerte_detention_sans_experience_marche% == 1) ? "🟠 Expérience ou connaissance limitée" : "🟢 Cohérent"'],
    ['name' => 'alerte_profil_instable', 'formula' => '((%d1_tolerance_declarative% >= 8) && (%d3_comportement_risque% <= 4)) ? 2: ((%d1_tolerance_declarative% >= 6) && (%d3_comportement_risque% <= 5)) ? 1: 0'],
    ['name' => 'alerte_profil_instable_echelle', 'formula' => '(%alerte_profil_instable% == 2) ? "🔴 Profil instable – contradiction forte déclaratif / comportemental" : (%alerte_profil_instable% == 1) ? "🟠 Vigilance – légère instabilité du profil" : "🟢 Profil stable"'],
    ['name' => 'alerte_effort_epargne', 'formula' => '((%risque_6_profil_investisseur% >= 8) && (%risque_5_profil_investisseur% <= 3)) ? 2: ((%risque_6_profil_investisseur% >= 5) && (%risque_5_profil_investisseur% <= 3)) ? 1: 0'],
