    ['name' => 'alerte_complexes_sans_experience', 'formula' => '((%niveau_connaissance_complexe% <= 2) && (%niveau_experience_complexe% <= 2)) ? 2: ((%niveau_connaissance_complexe% < 5) || (%niveau_experience_complexe% < 5)) ? 1: 0'],
    ['name' => 'alerte_complexes_sans_experience_echelle', 'formula' => '(%alerte_complexes_sans_experience% == 2) ? "🔴 Produits complexes interdits" : (%alerte_complexes_sans_experience% == 1) ? "🟠 Vigilance produits complexes" : "🟢 Cohérent"'],
    ['name' => 'alerte_horizon_incompatible', 'formula' => '((%preference_2_profil_investisseur% <= 3) && (%profil_risque_final% >= 7)) ? 2: ((%preference_2_profil_investisseur% <= 4) && (%profil_risque_final% >= 6)) ? 1: 0'],
    ['name' => 'alerte_horizon_incompatible_echelle', 'formula' => '(%alerte_horizon_incompatible% == 2) ? "🔴 Horizon incompatible avec le profil de risque" : (%alerte_horizon_incompatible% == 1) ? "🟠 Vigilance – horizon court pour ce profil" : "🟢 Cohérent"'],
    ['name' => 'blocage_depense_imprevue', 'formula' => '(%risque_12_profil_investisseur% >= 10) ? 2: (%risque_12_profil_investisseur% >= 5) ? 1: 0'],
    ['name' => 'blocage_produits_complexes_interdits', 'formula' => '((%produits_effet_de_levier_et_produits_boursiers_profil_investisseur% >= 1) && (%niveau_connaissance_complexe% <= 2) && (%niveau_experience_complexe% <= 2)) ? 2 : ((%produits_effet_de_levier_et_produits_boursiers_profil_investisseur% >= 1) && ((%niveau_connaissance_complexe% < 5) || (%niveau_experience_complexe% < 5))) ? 1 : 0'],
    ['name' => 'coherence_bloc_1', 'formula' => '(  (%blocage_produits_complexes_interdits% == 2)  || (%blocage_depense_imprevue% == 2)  || (%alerte_client_fragile% == 2)  || (%alerte_objectif_levier% == 2)  || (%alerte_detention_sans_experience_marche% == 2)) ? 2: (  (%blocage_produits_complexes_interdits% == 1)  || (%blocage_depense_imprevue% == 1)  || (%alerte_client_fragile% == 1)  || (%alerte_objectif_levier% == 1)  || (%alerte_detention_sans_experience_marche% == 1)) ? 1: 0'],
    ['name' => 'coherence_bloc_1_echelle', 'formula' => '(%coherence_bloc_1% == 2) ? "🔴 Incohérences détectées" : (%coherence_bloc_1% == 1) ? "🟠 Points d\'attention détectés" : "🟢 Profil cohérent"'],
    ['name' => 'engagement_extra_financier_score', 'formula' => '(%extra_financier_1_profil_investisseur% || 0)'],
