    ['name' => 'engagement_extra_financier_echelle', 'formula' => '(%engagement_extra_financier_score% <= 0) ? "Aucune préférence ESG" : "Client sensible ESG"'],
    ['name' => 'orientation_extra_financier_echelle', 'formula' => '(%orientation_extra_financier_score% <= 0) ? "🔴 Aucune orientation ESG" : (%orientation_extra_financier_score% <= 3.5) ? "🟠 Orientation ESG légère" : (%orientation_extra_financier_score% < 7) ? "🟠 Orientation ESG modérée" : "🟢 Orientation ESG affirmée"'],
    ['name' => 'thematiques_esg_echelle', 'formula' => '(%thematiques_esg_score% <= 0) ? "Aucune préférence thématique" :(%thematiques_esg_score% <= 3.5) ? "Sensibilité thématique faible" :(%thematiques_esg_score% <= 7) ? "Sensibilité thématique modérée" :"Sensibilité thématique forte"'],
    ['name' => 'rintensite_extra_financier_echelle', 'formula' => '(%intensite_extra_financier_score% <= 0) ? "Part non renseignée" :(%intensite_extra_financier_score% <= 2) ? "Engagement ESG limité" :(%intensite_extra_financier_score% <= 6) ? "Engagement ESG significatif" :"Engagement ESG prioritaire"'],
    ['name' => 'score_esg', 'formula' => '(%engagement_extra_financier_score% <= 0) ? 0 : (((%orientation_extra_financier_score% || 0) +(%thematiques_esg_score% || 0) +(%intensite_extra_financier_score% || 0)) / 3)'],
    ['name' => 'alerte_esg_echelle', 'formula' => '(%score_esg% <= 0) ? "🔴 Aucune préférence ESG" : (%score_esg% <= 3) ? "🟠 Sensibilité ESG faible" : (%score_esg% <= 6) ? "🟢 Sensibilité ESG modérée" : (%score_esg% <= 8) ? "🟢 Sensibilité ESG affirmée" : "🟢 Préférences ESG fortes"'],
